<?php require 'auth.php'; require_login(); $u=usuario_actual(); $msg=''; if($_SERVER['REQUEST_METHOD']==='POST'){ $nombre=trim($_POST['nombre']??'');$pass=$_POST['contrasena']??''; if($nombre){$sql=$pass?'UPDATE usuarios SET nombre=?,contrasena=? WHERE id_usuario=?':'UPDATE usuarios SET nombre=? WHERE id_usuario=?';$st=$pdoAuth->prepare($sql);$st->execute($pass?[$nombre,password_hash($pass,PASSWORD_DEFAULT),$u['id_usuario']]:[$nombre,$u['id_usuario']]);$_SESSION['usuario']=$u['id_usuario'];$msg='Perfil actualizado correctamente.';$u=usuario_actual();}} ?><!doctype html><html lang="es"><head><meta charset="utf-8"><link rel="stylesheet" href="css/styles.css"><title>Mi perfil</title></head><body class="login-page"><form method="post" class="card login-card"><h1>Mi perfil</h1><?php if($msg): ?><div class="alert-success"><?=htmlspecialchars($msg)?></div><?php endif; ?><label>Nombre de usuario<input name="nombre" value="<?=htmlspecialchars($u['nombre'])?>" required></label><label>Nueva contraseña<input type="password" name="contrasena" minlength="8" placeholder="Dejar vacía para conservarla"></label><button class="btn btn-primary">Guardar cambios</button><a href="index.php" class="btn btn-ghost">Volver</a></form></body></html>